 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y,x))
            bounds = {}
            for color, pts in colors.items():
                bounds[color] = (min(y for y,x in pts), min(x for y,x in pts), max(y for y,x in pts), max(x for y,x in pts))
            ordered = sorted(colors, key=lambda k: (-(bounds[k][2]-bounds[k][0]+1)*(bounds[k][3]-bounds[k][1]+1), k))
            remap = {old: new for old, new in zip(ordered, reversed(ordered))}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
